// === Tab: mySketch ===
const MAX_xVel = 3;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	noStroke();
	p = [];
	for (i=399; i--;) {
		p.push({
			x: width/2,
			y: height/8,
			xVel: random(-MAX_xVel, MAX_xVel),
			yVel: random(-3, 4),
			size: random(1, 9),
			life: random(1, 10),
			color: random(0,360)
		})
	}
}

function draw() {
	fill("#00001337");
	rect(0, 0, width, height);
	for (particle of p)	{
		colorMode(HSL)
		fill(particle.color, 100, 50);
		ellipse(particle.x, particle.y, particle.size, particle.size);
		particle.x += particle.xVel;
		particle.y += particle.yVel;
		particle.yVel += .1
		if (particle.y > height-particle.size) particle.yVel *= -.8
		if (particle.x > width) particle.xVel *= -.8
		if (particle.x < 0) particle.xVel *= -.8
		particle.life -= .01
		if (particle.life<0)
		{
			particle.life = random(1, 10)
			particle.x = width/2,
			particle.y = height/8,
			particle.xVel = random(-MAX_xVel, MAX_xVel),
			particle.yVel = random(-3, 4),
			particle.size = random(1, 9),
			particle.life = random(1, 10),
			particle.color = random(0,360)
		}
		if (abs(particle.yVel)<0.001337) particle.life=0
	}
}

